    for c in cnt:
        if c==bg: continue
        if any(sum(g[r][k]==c for r in range(h))>=2 for k in range(w)):
            bar=c; break
    # scan columns: find vertical runs of bar with length>=2, fill their TOP row only
    cols_seen=set()
