        r=0
        while r<h:
            if g[r][k]==bar and (r,k) not in cols_seen:
                r0=r
                while r<h and g[r][k]==bar:
                    r+=1
                if r-r0>=2:
                    d=-1 if k==w-1 else 1
                    c2=k+d
                    while 0<=c2<w:
                        v=g[r0][c2]
                        if v==bar: break
                        if v!=bg:
                            o[r0][c2]=4; break
                        o[r0][c2]=5
                        c2+=d
                for rr in range(r0,r): cols_seen.add((rr,k))
            else: r+=1
    return o
