from collections import Counter
def solve(g):
    o=[r[:] for r in g]; h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    bar=None
    for c in cnt:
        if c!=bg and any(sum(g[r][k]==c for r in range(h))>=2 for k in range(w)):
            bar=c; break
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,bar)]
    mcol=marks[0][0] if False else g[marks[0][0]][marks[0][1]]
    barinfo=[]
    for k in range(w):
        r=0
        while r<h:
            if g[r][k]==bar:
                r0=r
                while r<h and g[r][k]==bar: r+=1
                if r-r0>=2: barinfo.append({'k':k,'start':r0})
            else: r+=1
    barinfo.sort(key=lambda b:b['k'])
    L,R=barinfo[0],barinfo[1]
    # left bar shoots rightward on rows left.start + delta, delta = marker_row - right.bar_start
    for d_ in {m[0]-R['start'] for m in marks}:
        rr=L['start']+d_
        if 0<=rr<h:
            c=L['k']+1
            while c<w:
                v=g[rr][c]
                if v==bar: break
                if v not in (bg,):
                    o[rr][c]=4; break
                o[rr][c]=mcol
                c+=1
    for d_ in {m[0]-L['start'] for m in marks}:
        rr=R['start']+d_
        if 0<=rr<h:
            c=R['k']-1
            while c>L['k']:
                v=g[rr][c]
                if v==bar: break
                if v not in (bg,):
                    o[rr][c]=4; break
                o[rr][c]=mcol
                c-=1
    return o
