def solve(g):
    o=[r[:] for r in g]; h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    bar=None
    for c in cnt:
        if c!=bg and any(sum(g[r][k]==c for r in range(h))>=2 for k in range(w)):
            bar=c; break
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,bar)]
    mcol=g[marks[0][0]][marks[0][1]]
    barinfo=[]
    for k in range(w):
        r=0
        while r<h:
            if g[r][k]==bar:
                r0=r
                while r<h and g[r][k]==bar: r+=1
                if r-r0>=2: barinfo.append({'k':k,'start':r0})
            else: r+=1
    barinfo.sort(key=lambda b:b['k'])
    A,B=barinfo[0],barinfo[-1]   # A = left bar, B = right bar
    # A shoots RIGHT toward other side; delta rows from markers relative to B's start.
    for src,delta_src in [(A,{m[0]-B['start'] for m in marks}),
                          (B,{m[0]-A['start'] for m in marks})]:
        for d_ in delta_src:
            rr=src['start']+d_
            if 0<=rr<h:
                step=1 if src is A else -1
                c=src['k']+step
                while 0<=c<w:
                    v=g[rr][c]
                    if v==bar: break
                    if v not in (bg,):
                        o[rr][c]=4; break
                    o[rr][c]=mcol
                    c+=step
    return o
