def solve(g):
    o=[r[:] for r in g]; h,w=len(g),len(g[0])
    cc=Counter(x for r in g for x in r)
    bg=cc.most_common(1)[0][0]
    others={c:n for c,n in cc.items() if c!=bg}
    mcol=min(others,key=lambda c:others[c])
    barcols=sorted(k for k in range(w) if any(g[r][k] not in (mcol,bg) for r in range(h)))
    A,B=barcols[0],barcols[-1]
    marks=[(r,k) for r in range(h) for k in range(w) if g[r][k]==mcol]
    def sp(k):
        rr=[r for r in range(h) if g[r][k] not in (mcol,bg)]
        return min(rr),max(rr)
    sa,sb_=sp(A); ra_,rb_=sp(B)
    ref = A if all(sa<=r<=sb_ for r,_ in marks) else B
    rstart = sa if ref==A else sb_
    offs={r-rstart for r,_ in marks}
    def ray(r,c0,dc):
        step=1 if dc>0 else -1
        for c in range(c0+step,w,step):
            v=g[r][c]
            if v not in (mcol,bg): break
            if v==mcol:
                o[r][c]=4; return
            o[r][c]=mcol
    for off in offs:
        ray(ra_+off,A,1)   # left bar fires rightward
        ray(sa+off,B,-1)   # right bar fires leftward
    return o
